// Port of odht =0.3.1 `src/swisstable_group_query/no_simd.rs` (the group query of the oracle host,
// see mod.ts).
//
// PORT: `GroupWord` (u64) is a `bigint` kept in 0..2^64. `Option<usize>` is `number | undefined`; the
// `Iterator` impl is the JS iterator protocol (`next()` returns an `IteratorResult`).

export const GROUP_SIZE = 8;

// type GroupWord = u64;
// type NonZeroGroupWord = NonZeroU64;
type GroupWord = bigint;

const U64_MASK: GroupWord = (1n << 64n) - 1n;

export class GroupQuery implements IterableIterator<number> {
  constructor(
    public eq_mask: GroupWord,
    public empty_mask: GroupWord,
  ) {}

  // crate: odht-0.3.1/src/swisstable_group_query/no_simd.rs:20 from
  static from(group: Uint8Array, h2: number): GroupQuery {
    // Adapted from this gem:
    // https://github.com/rust-lang/hashbrown/blob/bbb5d3bb1c23569c15e54c670bc0c3669ae3e7dc/src/raw/generic.rs#L93-L109
    // which in turn is based on
    // http://graphics.stanford.edu/~seander/bithacks.html##ValueInWord
    //
    // Note the mask generated by the code below can contain false
    // positives. But we don't care because it's rare and we need
    // to compare keys anyway. In other words, a false positive here
    // has pretty much the same effect as a hash collision, something
    // that we need to deal with in any case anyway.

    const group_ = GroupWord_from_le_bytes(group);
    const cmp = group_ ^ repeat(h2);
    const high_bit_greater_than_128 = (~cmp & U64_MASK) & repeat(0x80);
    // `cmp.wrapping_sub(repeat(0x01))`
    const high_bit_greater_than_128_or_zero = (cmp - repeat(0x01)) & U64_MASK;
    const eq_mask = high_bit_greater_than_128_or_zero & high_bit_greater_than_128;

    const empty_mask = group_ & repeat(0x80);

    return new GroupQuery(eq_mask, empty_mask);
  }

  // crate: odht-0.3.1/src/swisstable_group_query/no_simd.rs:47 any_empty
  any_empty(): boolean {
    return this.empty_mask !== 0n;
  }

  // crate: odht-0.3.1/src/swisstable_group_query/no_simd.rs:52 first_empty
  first_empty(): number | undefined {
    // `Some((NonZeroGroupWord::new(self.empty_mask)?.trailing_zeros() / 8) as usize)`
    if (this.empty_mask === 0n) return undefined;
    return Math.floor(u64_trailing_zeros(this.empty_mask) / 8);
  }

  // impl Iterator for GroupQuery
  // crate: odht-0.3.1/src/swisstable_group_query/no_simd.rs:61 next
  next(): IteratorResult<number, undefined> {
    // `let index = NonZeroGroupWord::new(self.eq_mask)?.trailing_zeros() / 8;`
    if (this.eq_mask === 0n) return { done: true, value: undefined };
    const index = Math.floor(u64_trailing_zeros(this.eq_mask) / 8);

    // Clear the lowest bit
    // http://graphics.stanford.edu/~seander/bithacks.html#CountBitsSetKernighan
    this.eq_mask &= this.eq_mask - 1n;

    return { done: false, value: index };
  }

  [Symbol.iterator](): GroupQuery {
    return this;
  }
}

// crate: odht-0.3.1/src/swisstable_group_query/no_simd.rs:14 repeat
function repeat(byte: number): GroupWord {
  // `GroupWord::from_ne_bytes([byte; GROUP_SIZE])` (every byte is equal, so the byte order does not matter)
  return BigInt(byte) * 0x0101_0101_0101_0101n;
}

/** `GroupWord::from_le_bytes(*group)` */
function GroupWord_from_le_bytes(b: Uint8Array): GroupWord {
  const lo = (b[0]! | (b[1]! << 8) | (b[2]! << 16) | (b[3]! << 24)) >>> 0;
  const hi = (b[4]! | (b[5]! << 8) | (b[6]! << 16) | (b[7]! << 24)) >>> 0;
  return BigInt(lo) | (BigInt(hi) << 32n);
}

/** `u64::trailing_zeros` (64 for 0). */
function u64_trailing_zeros(x: bigint): number {
  if (x === 0n) return 64;
  let n = 0;
  while ((x & 1n) === 0n) {
    x >>= 1n;
    n++;
  }
  return n;
}
